## Phase 1: Infrastructure (~2-4 hours)

**1.1 Enable Mouse Mode**
- Remove early `return` in `setupMouseHandler()` (Board.tsx:1489)
- Test scroll wheel in supported terminals

**1.2 Create Hit Registry** (new file: `hit-registry.ts`)
```typescript
interface HitTarget {
  type: 'node' | 'fold-toggle' | 'link' | 'column-header';
  colIndex?: number;
  cardIndex?: number;
  subIndex?: number;
  nodeId?: string;
  linkUrl?: string;
}

interface HitRegion {
  x: number; y: number; width: number; height: number;
  target: HitTarget;
  zIndex: number;  // dialogs > cards > background
}

class HitRegistry {
  register(id: string, region: HitRegion): void;
  unregister(id: string): void;
  hitTest(screenX: number, screenY: number): HitTarget | null;  // Returns highest z-index match
}
```

**1.3 Create `useHitRegion` Hook**
```typescript
function useHitRegion(target: HitTarget, zIndex = 0) {
  const layout = useLayout();
  const registry = useContext(HitRegistryContext);
  useEffect(() => {
    const id = generateId();
    registry.register(id, { ...layout, target, zIndex });
    return () => registry.unregister(id);
  }, [layout.x, layout.y, layout.width, layout.height]);
}
```

