```typescript
function getNodeDisplayName(node: Node): string {
  switch (node.type) {
    case "folder":
    case "file":
      if (!node.fs_path) throw new Error(`${node.type} ${node.id} missing fs_path`);
      // ... extract name from path
    case "section":
