// 'i': Enter current node as board (like 'o' but stays in board view)
if (input === 'i' && card) {
  const targetId = card.node.link_to || card.node.id;
  const zoomed = buildBoardState(targetId);
  zoomed.zoomStack = [...s.zoomStack, s.rootId || ''];
