// todo → wip → done → dropped → todo
function getNextStatus(current: TaskStatus | null): TaskStatus {
  switch (current) {
    case "todo": return "wip";
    case "wip": return "done";
    case "done": return "dropped";
    case "dropped": return "todo";
    default: return "todo";
  }
}
